await (async (page) => {
 await page.reload(); const region=page.getByRole('region',{name:'Book workspace local preview'});await region.getByRole('heading',{name:'Lantern Garden',exact:true}).waitFor();
 await region.getByRole('textbox',{name:'Selected chapter title',exact:true}).fill('A-only unsubmitted rename');
 await page.evaluate(()=>{window.__renameSamples=[];window.__renameObserver=new MutationObserver(()=>{if(document.querySelector('section h1')?.textContent==="B's invented private book"){const v=document.querySelector('#workspace-rename-title')?.value;if(v!==undefined)window.__renameSamples.push(v);}});window.__renameObserver.observe(document.querySelector('section'),{subtree:true,childList:true,attributes:true});});
 await page.getByRole('button',{name:'Use Author B',exact:true}).click();await page.getByRole('button',{name:'Open B book',exact:true}).click();await region.getByRole('heading',{name:"B's invented private book",exact:true}).waitFor();
 const samples=await page.evaluate(()=>{window.__renameObserver.disconnect();return window.__renameSamples;});
 await page.reload();await region.getByRole('heading',{name:'Lantern Garden',exact:true}).waitFor();const notes=region.getByRole('textbox',{name:'Planning notes for this book',exact:true});await notes.fill('First notes');await page.getByRole('button',{name:'Pause next change',exact:true}).click();await region.getByRole('button',{name:'Apply book notes locally',exact:true}).click();await region.getByRole('status').filter({hasText:'Applying a change'}).waitFor();await notes.fill('Later typing retains focus');
 await page.getByRole('button',{name:'Release paused change',exact:true}).evaluate(el=>el.click());await region.getByRole('status').filter({hasText:'confirmed in this local test session only'}).waitFor();
 const focused=await page.evaluate(()=>document.activeElement?.id);return {source:'a0b896ad62325edc072cbc21753dec60208dc5a4',renameSamplesDuringB:samples,renameLeakObserved:samples.includes('A-only unsubmitted rename'),notesFocusAfterAcknowledgement:focused,notesFocusPass:focused==='workspace-book-notes'};
})(page);
